import{z as A,x as o,o as t,c as d,q as i,j as B,D as e,d as E,s as r,S as s,b as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"合成数据的去重与污染","description":"","frontmatter":{"title":"合成数据的去重与污染","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthetic-dedup-contamination.md","filePath":"llm/synthetic-dedup-contamination.md","lastUpdated":1791413859000}'),m={name:"llm/synthetic-dedup-contamination.md"};function p(h,a,C,D,c,u){const n=o("Mermaid");return t(),d("div",null,[a[2]||(a[2]=i('<h1 id="合成数据的去重与污染" tabindex="-1">合成数据的去重与污染 <a class="header-anchor" href="#合成数据的去重与污染" aria-label="Permalink to &quot;合成数据的去重与污染&quot;">​</a></h1><div class="epigraph"><p>合成管线里，去重不是清洗，是生成环内的一步：挡不住重复的生成器，会在几轮之内把题池唱成同一首歌。</p><footer>—— 据 Lee 等 2021 去重实证；Shumailov 等 2024 坍缩实证整理</footer></div><p><a href="/llm/synthetic-quality-filter">上一课</a>的关卡拦的是「坏样本」，本课拦的是「重复与泄漏」。字面与近重复去重在 <a href="/llm/minhash-dedup">MinHash / 精确去重</a>与<a href="/llm/semdedup">语义去重</a>已讲，评测去污染的流水线在<a href="/llm/decontamination-pipeline">去污染流水线</a>已立。本课写合成数据特有的三件事：模板共因让常规去重失效；污染入口从「爬到评测题」变成「教师会出评测题」；重复在闭环里是坍缩的燃料。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>合成的重复有一种常规管线看不见的形态：同一模板批量生成一千道题，表面字词全不同，模板层完全相同。n-gram 与 MinHash 在字面层工作，抓不住这种「换皮不换骨」；语义去重能抓一部分，但同时带来把「同题不同解」误删的风险。污染的入口则有两扇：教师预训练时见过基准题，生成时会不自觉地复刻其结构与数值；更糟的是操作性问题——为了让评测分好看，直接把基准题型喂给出题器。两扇门通向同一个结局：训练分与评测分双双上涨，泛化没动。<span class="marginnote">直觉类比：「换皮不换骨」像同一张卷子换封面印一千次——字面上没有两页相同，n-gram 自然抓不到，但考的是同一道题。学生刷一千遍同一题型，看着什么都会，换个数字就露馅；模板指纹就是掀开封面去看卷子的结构。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>去重四层，逐层收紧。精确哈希消灭字节级复制；MinHash 加 LSH 估计 Jaccard 抓近重复；嵌入空间语义去重抓释义级重复；再加一层模板指纹——抽取指令的骨架（句式结构、槽位类型、答案形态），在骨架层去重，专治模板共因。同一道数学题保留多条解法是资产不是重复，所以骨架比对要允许答案与解法字段带差异度预算，这是合成管线与网页管线在去重上最实质的分歧。</p><p>污染扫描三件套。与基准的字面与近字面重叠检测：n-gram 加嵌入近邻双通道。金丝雀：往训练池投放带标记的合成样本，评测时检查是否被背诵——它同时审计生成器与数据管理链路。生成器隔离审计：训练集与评测集的生成器、模板库、种子是否共享；共享即视为系统性污染嫌疑，不必逐条找证据。三件套的结论与<a href="/llm/eval-contamination">训练-评测污染检测</a>的语料审计口径合并使用。</p>',8)),(t(),B(s,null,{default:e(()=>[r(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAND%5B%22%E8%BF%87%E6%BB%A4%E5%90%8E%E5%80%99%E9%80%89%22%5D%20--%3E%20EX%5B%22%E7%B2%BE%E7%A1%AE%E5%93%88%E5%B8%8C%22%5D%0A%20%20EX%20--%3E%20MH%5B%22MinHash%2FLSH%20%E8%BF%91%E9%87%8D%E5%A4%8D%22%5D%0A%20%20MH%20--%3E%20SEM%5B%22%E8%AF%AD%E4%B9%89%E5%8E%BB%E9%87%8D%EF%BC%9A%E5%B5%8C%E5%85%A5%E8%81%9A%E7%B1%BB%22%5D%0A%20%20SEM%20--%3E%20TPL%7B%22%E6%A8%A1%E6%9D%BF%E6%8C%87%E7%BA%B9%E9%87%8D%E5%A4%8D%EF%BC%9F%22%7D%0A%20%20TPL%20--%3E%7C%E6%98%AF%E4%B8%94%E8%B6%85%E5%B7%AE%E5%BC%82%E9%A2%84%E7%AE%97%7C%20CUT%5B%22%E5%88%A0%E6%88%96%E5%90%88%E5%B9%B6%22%5D%0A%20%20TPL%20--%3E%7C%E5%90%A6%7C%20SCAN%5B%22%E9%87%91%E4%B8%9D%E9%9B%80%E4%B8%8E%E6%B1%A1%E6%9F%93%E6%89%AB%E6%8F%8F%22%5D%0A%20%20SCAN%20--%3E%20IN%5B%22%E5%85%A5%E5%BA%93%EF%BC%8C%E5%B8%A6%E5%8E%BB%E9%87%8D%E7%89%88%E6%9C%AC%E5%8F%B7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[E("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,[E("重复不是中性填充。"),l("a",{href:"/llm/model-collapse-empirics"},"模型坍缩的实证"),E("的机制里，递归训练的损害正是从高频模式被反复强化开始的：模板共因若不去，等价于把训练分布往几个模板峰上压，坍缩的先兆——尾部丢失、熵收缩——会提前出现。重复还放大隐私面：语言模型对重复串的背诵概率显著更高，合成批次若夹带种子里的个人信息，重复会让它从「可提取」变成「必然吐出」。污染的机制则更隐蔽：它是过拟合到评测生成过程的学习——模型不需要学会任务，只需要学会「这类生成器会出什么」，模板正则性就是全部答案。这也是为什么去污染课强调语料审计是一等证据：成员推断只能补刀，不能洗白。")],-1)),(t(),B(s,null,{default:e(()=>[r(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E7%94%9F%E6%88%90%E5%99%A8%E6%89%B9%E9%87%8F%E5%87%BA%E9%A2%98%22%5D%20--%3E%20R%5B%22%E6%A8%A1%E6%9D%BF%E5%85%B1%E5%9B%A0%E4%B8%8D%E5%8E%BB%2C%20%E9%87%8D%E5%A4%8D%E6%A0%B7%E6%9C%AC%E5%9B%9E%E7%81%8C%E8%AE%AD%E7%BB%83%22%5D%0A%20%20R%20--%3E%20P%5B%22%E8%AE%AD%E7%BB%83%E5%88%86%E5%B8%83%E5%8E%8B%E5%90%91%E5%B0%91%E6%95%B0%E6%A8%A1%E6%9D%BF%E5%B3%B0%22%5D%0A%20%20P%20--%3E%20C1%5B%22%E5%85%88%E5%85%86%E4%B8%80%3A%20%E5%B0%BE%E9%83%A8%E6%A0%B7%E6%9C%AC%E4%B8%A2%E5%A4%B1%22%5D%0A%20%20P%20--%3E%20C2%5B%22%E5%85%88%E5%85%86%E4%BA%8C%3A%20%E8%BE%93%E5%87%BA%E7%86%B5%E6%94%B6%E7%BC%A9%22%5D%0A%20%20C1%20--%3E%20COL%5B%22%E5%9D%8D%E7%BC%A9%3A%20%E9%A2%98%E6%B1%A0%E5%94%B1%E6%88%90%E5%90%8C%E4%B8%80%E9%A6%96%E6%AD%8C%22%5D%0A%20%20C2%20--%3E%20COL%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">为什么重要：语言模型对重复出现的字符串背诵概率显著更高——一个出现上百次的手机号几乎必然被记住、被吐出。合成批次若夹带种子里的个人信息又不去重，等于把隐私数据复制一百遍再喂给模型；Kandpal 等 2022 把去重与泄露率直接挂钩就是这个道理。</span></p><p><span class="marginnote">Lee 等 2021 的口径：对 C4 去重后训练效率提升，训练集中可被背诵的测试串大幅减少；Kandpal 等 2022 进一步把去重与隐私泄露率挂钩。合成管线照单全收这两条，只多加一条：模板层也要去。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>四层去重的阈值都是精度与覆盖的权衡：语义层阈值松了删资产（多解法、多表述），紧了留近重复。模板指纹的抽取本身可能过拟合到某种题式，把真正不同的任务误判为同模板——骨架层去重要抽样人审。污染扫描对释义级污染的召回有限，金丝雀只能证明被测链路干净，不能证明没投放过的路径干净。评测集若也来自合成（本课程后面有专课），隔离审计要升级到生成器级：n-gram 重叠合格不等于同源风险解除。<span class="marginnote">常见误区：初学者容易以为去重阈值越紧越好。语义层收得过紧，会把「同一道题的多种解法」「同一事实的多种表述」当重复删掉——这些恰是训练资产。所以骨架比对要给解法字段留差异度预算，并辅以抽样人审。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>去重四层：精确、MinHash、语义、模板指纹；合成特有的是模板共因。</li><li>同题多解是资产，骨架去重要带差异度预算。</li><li>污染两扇门：教师复刻基准与操作性出题；生成器隔离是结构性防线。</li><li>重复是坍缩与背诵的燃料，去重是生成环内步骤，不是事后清洗。</li><li>金丝雀与语料审计是一等证据，成员推断只补刀。</li><li>出处：Lee 等 2021；Kandpal 等 2022；Shumailov 等 2024。</li></ul>',6))])}const T=A(m,[["render",p]]);export{_ as __pageData,T as default};
